/* Wattle & Co (Retail) - source database seed for the pipeline Copy demo
   Plays the role of: Retail back office, inventory and replenishment (on-prem SQL Server)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.stores; DROP TABLE IF EXISTS src.stock_issues; DROP TABLE IF EXISTS src.stage_stores; DROP TABLE IF EXISTS src.stage_stock_issues;
CREATE TABLE src.stores (store_id INT NOT NULL, store_code NVARCHAR(30), store_name NVARCHAR(100), store_format NVARCHAR(30), state NVARCHAR(40), status NVARCHAR(30), store_tier INT, weekly_sales_kaud DECIMAL(12,1), open_date DATE, last_modified DATETIME2(0), CONSTRAINT pk_stores PRIMARY KEY (store_id));
CREATE TABLE src.stock_issues (issue_id INT NOT NULL, store_id INT, issue_type NVARCHAR(30), priority INT, status NVARCHAR(30), raised_ts DATETIME2(0), resolved_ts DATETIME2(0), lost_sales_aud DECIMAL(12,2), units_affected DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_stock_issues PRIMARY KEY (issue_id));
CREATE TABLE src.stage_stores (release_day INT NOT NULL, store_id INT, store_code NVARCHAR(30), store_name NVARCHAR(100), store_format NVARCHAR(30), state NVARCHAR(40), status NVARCHAR(30), store_tier INT, weekly_sales_kaud DECIMAL(12,1), open_date DATE, last_modified DATETIME2(0), area_manager NVARCHAR(50));
CREATE TABLE src.stage_stock_issues (release_day INT NOT NULL, issue_id INT, store_id INT, issue_type NVARCHAR(30), priority INT, status NVARCHAR(30), raised_ts DATETIME2(0), resolved_ts DATETIME2(0), lost_sales_aud DECIMAL(12,2), units_affected DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.stores', 'area_manager') IS NULL
        EXEC('ALTER TABLE src.stores ADD area_manager NVARCHAR(50) NULL');
    DELETE t FROM src.stores t WHERE EXISTS (SELECT 1 FROM src.stage_stores s WHERE s.release_day = @day AND s.store_id = t.store_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.area_manager = s.area_manager FROM src.stores t JOIN src.stage_stores s ON s.store_id = t.store_id AND s.release_day = 3');
    DELETE t FROM src.stock_issues t WHERE EXISTS (SELECT 1 FROM src.stage_stock_issues s WHERE s.release_day = @day AND s.issue_id = t.issue_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.stores) AS stores, (SELECT COUNT(*) FROM src.stock_issues) AS stock_issues;
END;
GO
