    INSERT INTO src.stores (store_id, store_code, store_name, store_format, state, status, store_tier, weekly_sales_kaud, open_date, last_modified) SELECT store_id, store_code, store_name, store_format, state, status, store_tier, weekly_sales_kaud, open_date, last_modified FROM src.stage_stores WHERE release_day = @day;
    INSERT INTO src.stock_issues (issue_id, store_id, issue_type, priority, status, raised_ts, resolved_ts, lost_sales_aud, units_affected, description, last_modified) SELECT issue_id, store_id, issue_type, priority, status, raised_ts, resolved_ts, lost_sales_aud, units_affected, description, last_modified FROM src.stage_stock_issues WHERE release_day = @day;
